import java.util.*;

class Solution {
    public int[] sortedSquares(int[] nums) {
        int left = 0, right = nums.length - 1, write = nums.length - 1;
        int[] result = new int[nums.length];
        while (left <= right) {
            int leftSq = nums[left] * nums[left];
            int rightSq = nums[right] * nums[right];
            if (leftSq > rightSq) {
                result[write--] = leftSq;
                left++;
            } else {
                result[write--] = rightSq;
                right--;
            }
        }
        return result;
    }
}
